%%\ Hybrid Traditional + AI Computer Vision Pipeline
close all; clear; clc;
rng(42); % Reproducible K-means cluster assignments

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

% ---------------------------------------------------
% Section 1: Load Image and AI Network
% ---------------------------------------------------
targetImage = imread('peppers.png'); % Built-in RGB sample image

disp('Loading pre-trained AI network (SqueezeNet)...'); %[output:559221e8]
net = squeezenet;
disp('Network loaded.'); %[output:27bad89e]

% ---------------------------------------------------
% Section 2: Traditional Method (Color Segmentation using K-Means)
% Role: Isolate the main object of interest using a traditional algorithm.
% ---------------------------------------------------
disp('Applying traditional color segmentation (K-Means)...'); %[output:1b35adfd]

% Convert RGB to CIE L*a*b* and cluster on chrominance channels (a*, b*)
imgLab = rgb2lab(targetImage);
ab = imgLab(:, :, 2:3);
ab = im2single(ab);
pixelLabels = imsegkmeans(ab, 2); % Cluster pixels into 2 color groups

% Create binary mask for the target object (switch to == 1 if inverted)
mask = (pixelLabels == 2);

% Apply mask to original image (zero out background pixels to black)
isolatedObject = targetImage;
isolatedObject(repmat(~mask, 1, 1, 3)) = 0;

% ---------------------------------------------------
% Section 3: AI Method (Image Classification)
% Role: Use deep learning to classify the isolated object.
% ---------------------------------------------------
disp('Running AI classification on the isolated object...'); %[output:66c03df7]

% SqueezeNet expects 227x227x3 RGB input
inputSize = net.Layers(1).InputSize;
resizedObject = imresize(isolatedObject, [inputSize(1) inputSize(2)]);
[YPred, probs] = classify(net, resizedObject);

% Baseline comparison: Classify the unsegmented raw image (AI-only)
resizedRaw = imresize(targetImage, [inputSize(1) inputSize(2)]);
[YPredRaw, probsRaw] = classify(net, resizedRaw);

% ---------------------------------------------------
% Section 4: Results Analysis & Screenshot Export
% ---------------------------------------------------
% Figure 1: All 4 pipeline stages (2x2 layout prevents title overlap)
f1 = figure('Name', 'Hybrid Pipeline Images'); %[output:447f0f1b]
tiledlayout(2, 2, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:447f0f1b]

nexttile; imshow(targetImage);    title('1. Original Image'); %[output:447f0f1b]
nexttile; imshow(mask);           title('2. Traditional Mask (K-Means)'); %[output:447f0f1b]
nexttile; imshow(isolatedObject); title('3. Isolated Object (Input to AI)'); %[output:447f0f1b]
nexttile; imshow(resizedObject);  title(sprintf('4. Resized Input (%s)', string(YPred))); %[output:447f0f1b]

saveas(f1, fullfile('screenshots', '01_hybrid_pipeline.png')); %[output:447f0f1b]

% Figure 2: Side-by-side comparison of AI-Only vs. Hybrid Pipeline
f2 = figure('Name', 'AI-Only vs Hybrid Comparison'); %[output:2a5fd65c]
tiledlayout(1, 2, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:2a5fd65c]

nexttile; imshow(resizedRaw); %[output:2a5fd65c]
title(sprintf('AI-Only: %s (%.1f%%)', string(YPredRaw), max(probsRaw) * 100)); %[output:2a5fd65c]

nexttile; imshow(resizedObject); %[output:2a5fd65c]
title(sprintf('Hybrid: %s (%.1f%%)', string(YPred), max(probs) * 100)); %[output:2a5fd65c]

saveas(f2, fullfile('screenshots', '02_ai_vs_hybrid_comparison.png')); %[output:2a5fd65c]

% Print detailed console metrics
fprintf('\n--- Hybrid Pipeline Results ---\n'); %[output:8a686874]
fprintf('The AI model classified the isolated object as: %s\n', string(YPred)); %[output:57f0cf2a]
fprintf('Confidence (Probability): %.2f%%\n', max(probs) * 100); %[output:7ac5187d]

fprintf('\n--- Copy into README.md ---\n'); %[output:6ba87a66]
fprintf('| AI-Only (Unsegmented Raw Image) | %s | %.2f%% |\n', string(YPredRaw), max(probsRaw) * 100); %[output:030ee3ca]
fprintf('| Hybrid Pipeline (K-Means + SqueezeNet) | %s | %.2f%% |\n', string(YPred), max(probs) * 100); %[output:03e0d7a5]

% Display Top-3 class predictions for the hybrid pipeline
[sortedProbs, idx] = sort(probs, 'descend');
classNames = net.Layers(end).Classes;
fprintf('\n--- Top-3 Hybrid Predictions ---\n'); %[output:74a41257]
for k = 1:3 %[output:group:12b6f2b4]
    fprintf('%d. %-18s : %.2f%%\n', k, string(classNames(idx(k))), sortedProbs(k) * 100); %[output:7c752f58]
end %[output:group:12b6f2b4]

